<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Models\Users;use App\Models\Conversation;use App\Models\Message;
class CoinTransferController extends Controller{
 public function send(Request $r){$me=auth('app_users')->user();if(!$me)return response()->json(['status'=>false],401);$v=$r->validate(['receiver_id'=>'required|integer|min:1','coins'=>'required|integer|min:1|max:10000','request_key'=>'required|uuid']);if($v['receiver_id']==$me->id)return response()->json(['status'=>false,'message'=>'Choose another person.'],422);
 return DB::transaction(function()use($v,$me){$users=Users::whereIn('id',[$me->id,$v['receiver_id']])->orderBy('id')->lockForUpdate()->get()->keyBy('id');$a=$users->get($me->id);$b=$users->get($v['receiver_id']);if(!$a||!$b||$a->is_block||$b->is_block||in_array($b->id,explode(',',(string)$a->blocked_users))||in_array($a->id,explode(',',(string)$b->blocked_users)))return response()->json(['status'=>false,'message'=>'Coin sharing is unavailable for this connection.'],403);
 $old=DB::table('coin_transfers')->where('sender_id',$me->id)->where('request_key',$v['request_key'])->first();if($old){if($old->receiver_id!=$b->id||$old->coins!=$v['coins'])return response()->json(['status'=>false,'message'=>'Transfer request already used.'],409);return response()->json(['status'=>true,'message'=>'Coins already delivered.','balance'=>(int)$a->wallet,'transaction_id'=>$old->id]);}
 if((int)$a->wallet<$v['coins'])return response()->json(['status'=>false,'message'=>'Not enough gift coins. Reload your account, then buy coins.'],402);
 $ids=[$a->id,$b->id];sort($ids);$cid=implode('_',$ids);Conversation::firstOrCreate(['conversation_id'=>$cid],['user_a'=>$ids[0],'user_b'=>$ids[1]]);$c=Conversation::where('conversation_id',$cid)->lockForUpdate()->first();if($c->blocked_by_a||$c->blocked_by_b)return response()->json(['status'=>false,'message'=>'This conversation is blocked.'],403);
 $a->wallet=(int)$a->wallet-$v['coins'];$a->save();$b->wallet=(int)$b->wallet+$v['coins'];$b->total_collected=(int)$b->total_collected+$v['coins'];$b->save();$id=DB::table('coin_transfers')->insertGetId(['sender_id'=>$a->id,'receiver_id'=>$b->id,'coins'=>$v['coins'],'request_key'=>$v['request_key'],'created_at'=>now(),'updated_at'=>now()]);\App\Services\FundedCoins::move($a->id,$b->id,$v['coins']);$body='✨ '.$v['coins'].' gift coins shared';Message::create(['conversation_id'=>$cid,'sender_id'=>$a->id,'receiver_id'=>$b->id,'message_type'=>'coins','body'=>$body]);$c->last_message=$body;$c->last_message_at=now();$c->last_message_by=$a->id;$c->save();return response()->json(['status'=>true,'message'=>'Gift coins delivered.','balance'=>(int)$a->wallet,'transaction_id'=>$id]);});
 }
}
